import type { OperationTrace, PipelineTrace, Role } from './trace';

export type Request = { runId: string; attemptId: string; correlationId: string; role: Role; instructionVersion: string; schemaVersion: string; configVersion: string; input: unknown; signal: AbortSignal };
export interface FakeTransport { execute(request: Request): Promise<unknown> }
export class Scheduler {
  private deadline: number;
  constructor(private transport: FakeTransport, private trace: PipelineTrace, private options: { timeoutMs: number; totalTimeoutMs: number; signal?: AbortSignal; instructionVersion: string; schemaVersion: string; configVersion: string }) { this.deadline = Date.now() + options.totalTimeoutMs; }
  async call(role: Role, input: unknown, validate: (value: unknown) => boolean): Promise<unknown | undefined> {
    if (this.trace.consumed >= 7 || this.options.signal?.aborted || Date.now() >= this.deadline) return undefined;
    const attemptId = `${this.trace.runId}-${++this.trace.consumed}`;
    this.trace.attempts[role] = (this.trace.attempts[role] ?? 0) + 1;
    const operation: OperationTrace = { attemptId, correlationId: attemptId, role, status: 'error', durationMs: 0, instructionVersion: this.options.instructionVersion, schemaVersion: this.options.schemaVersion, configVersion: this.options.configVersion };
    this.trace.operations.push(operation);
    const started = Date.now();
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    let onAbort: (() => void) | undefined;
    try {
      const cancelled = new Promise<never>((_, reject) => {
        onAbort = () => { controller.abort(); reject(new Error('cancelled')); };
        this.options.signal?.addEventListener('abort', onAbort, { once: true });
        if (this.options.signal?.aborted) onAbort();
        timer = setTimeout(() => { controller.abort(); reject(new Error('timeout')); }, Math.max(0, Math.min(this.options.timeoutMs, this.deadline - Date.now())));
      });
      const value = await Promise.race([Promise.resolve().then(() => this.transport.execute({ runId: this.trace.runId, attemptId, correlationId: attemptId, role, input, signal: controller.signal, instructionVersion: this.options.instructionVersion, schemaVersion: this.options.schemaVersion, configVersion: this.options.configVersion })), cancelled]);
      operation.status = validate(value) ? 'success' : 'invalid';
      if (operation.status === 'invalid') operation.cause = 'invalid_output';
      return operation.status === 'success' ? value : undefined;
    } catch (error) {
      const kind = error instanceof Error && (error.message === 'timeout' || error.message === 'cancelled') ? error.message : 'transport_error';
      operation.status = kind === 'timeout' ? 'timeout' : kind === 'cancelled' ? 'cancelled' : 'error';
      operation.cause = kind;
      return undefined;
    } finally {
      operation.durationMs = Date.now() - started;
      if (timer) clearTimeout(timer);
      if (onAbort) this.options.signal?.removeEventListener('abort', onAbort);
    }
  }
}
import OpenAI from 'openai';
import { zodTextFormat } from 'openai/helpers/zod';
import { normalizeWire, wireSchema } from './wire';
import { prompts } from './prompts';
import type { FakeTransport, Request } from './scheduler';
import type { Role } from './trace';

type Target = Exclude<Role, 'Repair'>;
type SDK = { responses: { create: (body: never, options: { signal: AbortSignal }) => Promise<{ status: string; output: { type: string; content?: { type: string }[] }[]; output_text: string }> } };
function target(request: Request): Target {
  if (request.role !== 'Repair') return request.role;
  const role = (request.input as { targetRole?: Role }).targetRole;
  if (!role || role === 'Repair') throw new Error('invalid target');
  return role;
}
// Strip review votes and extractor attribution from J. Wire aliases are mapped
// back to real candidate IDs before the adjudication reaches reconciliation.
function modelInput(role: Target, input: unknown): { payload: unknown; ids?: Map<string, string> } {
  if (role !== 'J') return { payload: input };
  const data = input as { snapshot: unknown; dispute: { candidateIds: string[] }; group?: { candidates: Record<string, unknown>[] } };
  const seen = new Set<string>();
  const ids = new Map<string, string>();
  const alternatives = (data.group?.candidates ?? []).flatMap(c => {
    const { extractorId: ignored, candidateId, ...rest } = c; void ignored;
    const key = JSON.stringify(rest);
    if (seen.has(key)) return [];
    seen.add(key);
    const alias = `candidate-${ids.size + 1}`;
    ids.set(alias, String(candidateId));
    return [{ candidateId: alias, ...rest }];
  });
  return { payload: { snapshot: data.snapshot, dispute: { ...data.dispute, candidateIds: alternatives.map(a => a.candidateId) }, alternatives }, ids };
}
export function openAIMultipassTransport(apiKey: string, modelName: string, client?: SDK): FakeTransport {
  const sdk = client ?? new OpenAI({ apiKey, timeout: 25000, maxRetries: 0 }) as unknown as SDK;
  return { async execute(request) {
    const role = target(request);
    const original = request.role === 'Repair' ? (request.input as { originalInput: unknown }).originalInput : request.input;
    const instructions = request.role === 'Repair' ? `${prompts.Repair}\n${prompts[role]}` : prompts[role];
    const model = modelInput(role, original);
    const response = await sdk.responses.create({ model: modelName, instructions, input: JSON.stringify(model.payload), text: { format: zodTextFormat(wireSchema(role), `multipass_${role.toLowerCase()}`) } } as never, { signal: request.signal });
    if (response.status !== 'completed') throw new Error('MODEL_INCOMPLETE');
    if (response.output.some(item => item.type === 'message' && item.content?.some(c => c.type === 'refusal'))) throw new Error('MODEL_REFUSAL');
    try {
      const parsed = normalizeWire(role, JSON.parse(response.output_text));
      if (role !== 'J') return parsed;
      const adjudication = parsed as { disputeId: string; resolution: { status: string; candidateId?: string } };
      if (adjudication.resolution.status === 'selected') adjudication.resolution.candidateId = model.ids?.get(adjudication.resolution.candidateId ?? '') ?? 'unrecognized-candidate';
      return adjudication;
    } catch { return null; }
  } };
}
# Definition of Done — Libeen V0 (Codex + Superpowers)

**Estado:** criterio operativo para la PoC; no acredita que exista ninguna funcionalidad implementada.  
**Ámbito:** tareas `LIB-001`–`LIB-013` del [DAG](../implementation/DAG.md).  
**Autoridad:** [AGENTS.md](../../AGENTS.md), [contrato de integración](../contracts/INTEGRATION_V0.md), [protocolo Codex](../implementation/CODEX_PROTOCOL.md) y el AI Task Brief asignado.  
**Propósito:** permitir ejecución **autónoma dentro de un brief autorizado** y verificar resultados sin aprobaciones intermedias del plan.

## Regla de autonomía de esta PoC

- **Asignar una tarea desbloqueada es autorizar su ejecución completa dentro del alcance y las rutas del brief.** Codex debe inspeccionar el contexto relevante, preparar su plan técnico interno y **comenzar a implementar sin esperar a que un humano apruebe el plan**.
- Puede dividir la tarea en pasos, crear y corregir tests, hacer self-review y repetir validaciones de forma autónoma. Utilizar Superpowers cuando ayude, sin volver a abrir la planificación funcional ni convertir sus pasos en gates de aprobación humana.
- Ante incertidumbre menor, elegir una solución conservadora compatible con contratos y documentar la suposición. Si una ambigüedad **material** impide satisfacer el contrato, detener **solo la parte afectada**, informar del bloqueo y continuar trabajo independiente cuando sea seguro.
- **Escalar únicamente** por cambios fuera del brief, modificación no autorizada de contratos/configuración/fixtures compartidos, secretos/permisos, operaciones irreversibles o efectos externos. No hacer `push`/`merge` ni modificar permisos del repositorio sin autorización expresa.
- Esta autonomía **no elimina** el control del asesor comercial dentro del producto: ningún mensaje real ni decisión sobre dinero se ejecuta automáticamente. Tampoco sustituye los gates de integración entre tareas.

## Checklist para que Codex declare una tarea lista para integrar

### 1. Objetivo y alcance

- [ ] El ID de tarea, dependencias y gate están identificados; las dependencias se comprobaron antes de empezar.
- [ ] El comportamiento del brief y sus criterios de aceptación están implementados, o las desviaciones quedan expresamente marcadas como pendientes.
- [ ] Solo se han modificado las **rutas autorizadas**; no hay refactors ni funcionalidades fuera de alcance.
- [ ] Las decisiones nuevas no contradicen las especificaciones del repositorio ni el lenguaje ubicuo: [Ubiquitous Language](ubiquitous-language.md).

### 2. Contratos y dominio

- [ ] Se respetan los contratos consumidos y producidos, las validaciones y la semántica de error del contrato V0.
- [ ] Ningún dato financiero desconocido se interpreta como `0`; las cifras aproximadas, conflictos, sujetos y evidencias siguen siendo trazables.
- [ ] Se distingue `ActionProposal` → `Draft` → aprobación → envío **simulado** → acuerdo del cliente; no se completa M5 por redactar o aprobar.
- [ ] No se infieren contenidos de audio sin transcripción, ni se descuentan dos veces deudas, ni se emiten aprobaciones financieras o garantías.
