export async function runPipeline(options: { runId: string; snapshot: Snapshot; transport: FakeTransport; signal?: AbortSignal; timeoutMs?: number; totalTimeoutMs?: number; instructionVersion?: string; schemaVersion?: string }) {
  const snapshot = freeze(structuredClone(options.snapshot));
  const trace = createTrace(options.runId);
  const scheduler = new Scheduler(options.transport, trace, { timeoutMs: options.timeoutMs ?? 10000, totalTimeoutMs: options.totalTimeoutMs ?? 30000, signal: options.signal, instructionVersion: options.instructionVersion ?? 'multipass-1', schemaVersion: options.schemaVersion ?? 'multipass-1', configVersion: `${snapshot.factSchema.version}/${snapshot.agentProfile.version}` });
  let repaired = false;
  const call = async (role: Role, input: unknown, schema: z.ZodType) => {
    const valid = (v: unknown) => schema.safeParse(v).success;
    const value = await scheduler.call(role, input, valid);
    if (value !== undefined) return value;
    const last = trace.operations.findLast(op => op.role === role);
    if (!repaired && last?.status === 'invalid') {
      repaired = true;
      return scheduler.call('Repair', freeze({ snapshot, targetRole: role, originalInput: input }), valid);
    }
    return undefined;
  };
  // Wait for every initial pass before choosing repair: multiple failures are
  // ambiguous and cannot be recovered with the single global repair budget.
  const roles = ['E1', 'E2', 'E3', 'S1'] as const;
  const initialInput = freeze({ snapshot });
  const initial = await Promise.all(roles.map(role => scheduler.call(role, initialInput, v => (role === 'S1' ? scan : extraction).safeParse(v).success)));
  const failed = initial.flatMap((value, index) => value === undefined ? [index] : []);
  if (failed.length === 1) {
    const index = failed[0];
    const role = roles[index];
    if (trace.operations.find(op => op.role === role)?.status === 'invalid') {
      repaired = true;
      const schema = role === 'S1' ? scan : extraction;
      initial[index] = await scheduler.call('Repair', freeze({ snapshot, targetRole: role, originalInput: initialInput }), v => schema.safeParse(v).success);
    }
  }
  const fail = (code: string) => { trace.finalStatus = 'failed'; trace.abstentionCauses.push(code); return { result: ReconciliationResultSchema.parse({ status: 'failed', code, message: 'Pipeline could not safely complete' }), trace, diagnostics: [] }; };
  if (initial.some(v => v === undefined)) return fail('initial_pass_failed');
  const candidates: ClaimCandidate[] = initial.slice(0, 3).flatMap((value, i) => extraction.parse(value).claims.map((claim, n) => ({ ...claim, extractorId: `E${i + 1}`, candidateId: `E${i + 1}-${n}` })));
  const grouped = groupClaims(candidates, snapshot.messages, { factSchema: snapshot.factSchema, assertions: snapshot.historicalAssertions, caseId: snapshot.caseId });
  const scanResult = scan.parse(initial[3]);
  const reviewed = await call('S2', freeze({ snapshot, candidates, groups: grouped.groups, diagnostics: grouped.diagnostics, signals: scanResult.candidates }), review);
  if (reviewed === undefined) { const failure = fail('protected_review_failed'); return { ...failure, diagnostics: grouped.diagnostics }; }
  const contextual = review.parse(reviewed);
  const expectedReviews = grouped.groups.flatMap(g => g.candidates.map(c => JSON.stringify([g.groupId, c.candidateId])));
  const actualReviews = contextual.reviews.map(r => JSON.stringify([r.groupId, r.candidateId]));
  if (actualReviews.length !== expectedReviews.length || new Set(actualReviews).size !== actualReviews.length || actualReviews.some(id => !expectedReviews.includes(id))) {
    const failure = fail('incomplete_contextual_review');
    return { ...failure, diagnostics: grouped.diagnostics };
  }
  const binding = bindSubjects({ groups: grouped.groups, reviews: contextual.reviews, messages: snapshot.messages, historicalAssertions: snapshot.historicalAssertions, knownSubjects: snapshot.knownSubjects, caseId: snapshot.caseId, diagnostics: grouped.diagnostics });
  const input = { factSchema: snapshot.factSchema, knownSubjects: [...snapshot.knownSubjects, ...binding.authorizedSubjects], historicalAssertions: snapshot.historicalAssertions, diagnostics: grouped.diagnostics, groups: binding.groups, reviews: contextual.reviews, messages: snapshot.messages, materialFieldIds: snapshot.materialFieldIds, schemaVersion: snapshot.factSchema.version, safety: { scanStatus: 'complete' as const, reviewStatus: 'complete' as const, candidates: [...scanResult.candidates, ...(contextual.candidates ?? [])], verdicts: contextual.verdicts, historicalBlockers: snapshot.historicalBlockers } };
  let result = reconcile(input);
  if (binding.status === 'human_review_required' && result.status !== 'failed') {
    result = ReconciliationResultSchema.parse({ status: 'human_review_required', disputes: result.status === 'human_review_required' ? result.disputes : [], reasons: [...(result.status === 'human_review_required' ? result.reasons : []), 'Subject attribution requires review'], trace: result.trace, safetyFindings: result.safetyFindings });
  }
  // Conflicting contextual verdicts for the same occurrence require human review;
  // corroborating votes do not erase an explicit refutation.
  const conflictingReview = grouped.groups.some(group => {
    const reviews = contextual.reviews.filter(r => r.groupId === group.groupId);
    return reviews.some(r => r.support === 'supported') && reviews.some(r => r.support === 'refuted');
  });
  if (conflictingReview && result.status === 'consolidated') {
    result = ReconciliationResultSchema.parse({ status: 'human_review_required', disputes: [], reasons: ['Conflicting contextual reviews'], trace: result.trace, safetyFindings: result.safetyFindings });
  }
  if (binding.status === 'success' && !conflictingReview && result.status === 'human_review_required' && result.disputes.length && trace.consumed < 7) {
    const dispute = result.disputes[0];
    const answer = await call('J', freeze({ snapshot, dispute, group: binding.groups.find(g => g.groupId === dispute.groupId), reviews: contextual.reviews, safetyFindings: result.safetyFindings }), AdjudicationResponseSchema);
    if (answer !== undefined) { const adjudication = AdjudicationResponseSchema.parse(answer); const next = reconcile({ ...input, adjudications: [adjudication] }); if (next.status !== 'failed') { result = next; trace.resolutions = adjudication.resolution.status === 'selected' ? 1 : 0; } }
  }
  result = ReconciliationResultSchema.parse(result);
  trace.disputes = result.status === 'human_review_required' ? result.disputes.length : 0;
  trace.finalStatus = result.status;
  if (result.status === 'human_review_required') trace.abstentionCauses = ['reconciliation_requires_review'];
  if (result.status === 'failed') trace.abstentionCauses = [result.code];
  return { result, trace, diagnostics: grouped.diagnostics, attributionDiagnostics: binding.diagnostics };
}
import { z } from 'zod';
import { SafetyFindingSchema } from './safety';
import { EvidenceRefSchema, FactValueSchema, InterpretationSchema, SubjectRefSchema } from '../../../contracts';

const id = z.string().min(1);
export const SpanSchema = z.strictObject({ start: z.number().int().nonnegative(), end: z.number().int().nonnegative(), text: z.string().min(1) }).refine(s => s.end > s.start);
export const OccurrenceRefSchema = z.strictObject({ messageId: id, statementSpan: SpanSchema, focusSpan: SpanSchema.optional(), previousAssertionId: id.optional() });
export const RawClaimSchema = z.strictObject({ fieldId: id, subjectRef: SubjectRefSchema, value: FactValueSchema.optional(), unit: id.optional(), period: id.optional(), incomeBasis: z.enum(['net', 'gross', 'unknown']).optional(), precision: z.enum(['explicit', 'approximate', 'ambiguous', 'inferred']), occurrence: OccurrenceRefSchema, evidenceRefs: z.array(EvidenceRefSchema).min(1), correction: z.strictObject({ dimension: z.enum(['value', 'incomeBasis', 'period', 'unit', 'subjectRef']), previousAssertionId: id }).optional() });
export const ClaimCandidateSchema = RawClaimSchema.extend({ candidateId: id, extractorId: id });
export const ClaimGroupSchema = z.strictObject({ groupId: id, occurrence: OccurrenceRefSchema, fieldId: id, semanticAtomicity: z.literal('context_review_required'), candidates: z.array(ClaimCandidateSchema).min(1) });
export const DisputeSchema = z.strictObject({ disputeId: id, groupId: id, candidateIds: z.array(id).min(1), reason: id, previousAssertionIds: z.array(id).optional(), evidenceRefs: z.array(EvidenceRefSchema).optional() });
export const ResolutionSchema = z.discriminatedUnion('status', [z.strictObject({ status: z.literal('selected'), candidateId: id, justification: id, evidenceRefs: z.array(EvidenceRefSchema).min(1) }), z.strictObject({ status: z.literal('unresolved'), justification: id })]);
export const AdjudicationResponseSchema = z.strictObject({ disputeId: id, resolution: ResolutionSchema });
export const SubjectAttributionSchema = z.strictObject({ kind: z.enum(['case', 'buying_unit', 'local_speaker', 'other_person', 'ambiguous']), messageId: id, evidenceRefs: z.array(EvidenceRefSchema).min(1), justification: id });
export const ContextReviewSchema = z.strictObject({ groupId: id, candidateId: id, atomicity: z.enum(['atomic', 'multiple', 'uncertain']), support: z.enum(['supported', 'refuted', 'uncertain', 'absent']), identitySpan: SpanSchema.optional(), evidenceRefs: z.array(EvidenceRefSchema).min(1), justification: id, subjectAttribution: SubjectAttributionSchema.optional() });
const trace = z.array(z.strictObject({ groupId: id, candidateId: id, decision: z.enum(['accepted', 'excluded', 'pending']), reason: id }));
export const ReconciliationResultSchema = z.discriminatedUnion('status', [
  z.strictObject({ status: z.literal('consolidated'), interpretation: InterpretationSchema, trace, safetyFindings: z.array(SafetyFindingSchema) }),
  z.strictObject({ status: z.literal('human_review_required'), disputes: z.array(DisputeSchema), reasons: z.array(id).min(1), trace, safetyFindings: z.array(SafetyFindingSchema) }),
  z.strictObject({ status: z.literal('failed'), code: id, message: id })
]);
export type ContextReview = z.infer<typeof ContextReviewSchema>;
export type Dispute = z.infer<typeof DisputeSchema>;
export type AdjudicationResponse = z.infer<typeof AdjudicationResponseSchema>;
export type OccurrenceRef = z.infer<typeof OccurrenceRefSchema>;
export type RawClaim = z.infer<typeof RawClaimSchema>;
export type ClaimCandidate = z.infer<typeof ClaimCandidateSchema>;
export type ClaimGroup = z.infer<typeof ClaimGroupSchema>;
import { writeFileSync } from 'node:fs';
import { it } from 'vitest';
import { cases, scenarios } from '../../src/fixtures';
import { configBundleRef, demoBundle } from '../../src/config';
import { OpenAIInterpreter, OpenAIDraftGenerator, openAITransport, classifyModelError, type ModelTransport } from '../../src/adapters/ai/openai';
import { evaluate } from '../../src/application/cases/evaluate';
import { CaseOrchestrator } from '../../src/application/cases/orchestrator';
import { MemoryCaseRepository } from '../../src/adapters/persistence/memory-case-repository';
import type { CaseEvent, CaseSnapshot, CaseView, Message } from '../../src/contracts';

// Intentionally skipped by normal pnpm test. Enable via scripts/eval-openai.mjs only.
const live = process.env.F01_EVAL_RUN === '1' ? it : it.skip;
type Scenario = 'B01' | 'B05' | 'B08' | 'B06' | 'B10' | 'C01';
type Settings = { scenarioIds: Scenario[]; repeat: number; mode: 'interpreter' | 'end-to-end'; maxRequests: number; allowFailures: boolean };
type Check = { name: string; pass: boolean; expected: unknown; actual: unknown };
type State = { snapshot: CaseSnapshot; action: string | null; errors: { code: string; message: string }[]; draft: string | null };
type Call = { index: number; kind: string; latencyMs: number; status: 'response' | 'error'; output?: unknown; diagnostic?: ReturnType<typeof classifyModelError> };
type Verdict = 'PASS' | 'PARTIAL' | 'FAIL' | 'BLOCKED';

function fixture(id: Scenario) {
  const caseId = ['B05', 'B06', 'B10'].includes(id) ? 'javier' : id === 'B08' ? 'rosa' : 'laura';
  const base = cases.find(c => c.caseId === caseId);
  if (!base) throw Error('Missing canonical fixture');
  const messages = structuredClone(base.messages);
  if (id === 'B06') {
    const source = messages.find(m => m.messageId === 'javier-m5');
    if (!source) throw Error('Missing trust fixture');
    source.content = { type: 'text', text: 'Antes de seguir necesito saber quién responde si esto no es fiable.' };
  }
  if (id === 'B10') {
    const addition = scenarios.find(s => s.id === 'javier-opt-out')?.additions[0];
    if (!addition) throw Error('Missing opt-out fixture');
    messages.push(structuredClone(addition));
  }
  return { caseId, messages };
}

function seed(caseId: string, messages: Message[]): CaseSnapshot {
  return {
    caseId, revision: 0, messages, assertions: [], knowledge: { facts: [] },
    goal: { id: 'qualification', description: 'Orientación comercial sintética', status: 'active' },
    workflowProgress: { workflowId: demoBundle.workflow.id, workflowVersion: demoBundle.workflow.version, milestones: [] },
    blockers: [], proposals: [], drafts: [], events: [], decisions: [], configBundleRef: structuredClone(configBundleRef),
    status: 'NEEDS_ADVISOR', analysisStatus: 'pending'
  };
}

const viewState = (v: CaseView): State => ({
  snapshot: v.snapshot, action: v.activeProposal?.actionType ?? null, draft: v.draft?.status ?? null,
  errors: v.errors.map(e => ({ code: e.code, message: e.message }))
});

async function execute(id: Scenario, index: number, transport: ModelTransport, mode: Settings['mode']): Promise<State> {
  const { caseId, messages } = fixture(id);
  const initial = seed(caseId, messages);
  const interpreter = new OpenAIInterpreter(transport);
  if (mode === 'interpreter') {
    if (id === 'C01') throw Error('C01 requires end-to-end');
    const interpreted = await interpreter.interpret({ caseSnapshot: initial, messages, factSchema: demoBundle.factSchema, agentProfile: demoBundle.agentProfile });
    if (!interpreted.ok) return { snapshot: { ...initial, analysisStatus: 'analysis_failed' }, action: null, draft: null, errors: [{ code: interpreted.error.code, message: interpreted.error.message }] };
    const result = evaluate({ ...initial, assertions: interpreted.value.assertions, blockers: interpreted.value.blockers, analysisStatus: 'complete' }, demoBundle, `run-${id}-${index}`, 'openai');
    if (!result.ok) return { snapshot: { ...initial, analysisStatus: 'analysis_failed' }, action: null, draft: null, errors: [{ code: result.error.code, message: result.error.message }] };
    return { snapshot: result.value.snapshot, action: result.value.snapshot.proposals.at(-1)?.actionType ?? null, errors: [], draft: null };
  }
  const repository = new MemoryCaseRepository([initial]);
  const orchestrator = new CaseOrchestrator({ repository, interpreter, draftGenerator: new OpenAIDraftGenerator(transport), mode: 'openai', getConfig: () => demoBundle });
  const analyze: CaseEvent = {
    eventId: `eval-${id}-${index}-initial`, caseId, type: 'CASE_ANALYSIS_REQUESTED', actor: 'advisor',
    occurredAt: '2026-05-03T10:00:00Z', expectedRevision: 0, payload: {}
  };
  let result = await orchestrator.handleEvent(analyze);
  if (id === 'C01') {
    const correction = scenarios.find(s => s.id === 'laura-gross-correction')?.additions[0];
    if (!correction) throw Error('Missing gross correction fixture');
    const stored = await repository.get(caseId);
    if (!stored.ok) throw Error('Cannot load case');
    const update: CaseEvent = {
      eventId: `eval-${id}-${index}-correction`, caseId, type: 'MESSAGE_RECEIVED', actor: 'customer',
      occurredAt: correction.occurredAt, expectedRevision: stored.value.revision, simulated: true,
      payload: { message: structuredClone(correction) }
    };
    result = await orchestrator.handleEvent(update);
  }
  if (result.ok) return viewState(result.value);
  const stored = await repository.get(caseId);
  return { snapshot: stored.ok ? stored.value : initial, action: null, draft: null, errors: [{ code: result.error.code, message: result.error.message }] };
}

function evaluateChecks(id: Scenario, state: State): Check[] {
  const facts = state.snapshot.knowledge.facts;
  const blockers = state.snapshot.blockers.filter(b => b.status === 'open').map(b => b.type);
  const fact = (fieldId: string, scope: string) => facts.find(f => f.fieldId === fieldId && f.subjectRef.scope === scope);
  const value = (f: (typeof facts)[number] | undefined): unknown => f && 'value' in f ? f.value : undefined;
  const hasEvidence = (f: (typeof facts)[number] | undefined, msg: string) => !!f?.evidenceRefs.some(e => e.messageId === msg);
  const checks: Check[] = [];
  const add = (name: string, pass: boolean, expected: unknown, actual: unknown) => checks.push({ name, pass, expected, actual });
  add('analysis_complete', state.snapshot.analysisStatus === 'complete', 'complete', state.snapshot.analysisStatus ?? 'missing');
  const expectedAction = id === 'B05' || id === 'B06' || id === 'B08' ? 'HANDOFF' : id === 'B10' ? 'STOP_CONTACT' : 'CLARIFY';
  add('commercial_action', state.action === expectedAction, expectedAction, state.action);
  if (id === 'B01' || id === 'C01') {
    const income = fact('declared_monthly_income', 'buying_unit');
    const savings = fact('available_savings', 'buying_unit');
    const debt = fact('monthly_debt', 'buying_unit');
    add('joint_income', value(income) === 3800 && hasEvidence(income, 'laura-m3'), '3800 @ laura-m3', income);
    add('savings_approximate', value(savings) === 18000 && savings?.status === 'approximate', 'approximate 18000', savings);
    add('car_debt', value(debt) === 250 && hasEvidence(debt, 'laura-m4'), '250 @ laura-m4', debt);
    add('no_false_trust_or_cost', !blockers.includes('TRUST') && !blockers.includes('COST'), 'no TRUST / COST', blockers);
    add('M3_blocked', state.snapshot.workflowProgress.milestones.find(m => m.milestoneId === 'M3')?.status === 'blocked', 'blocked', state.snapshot.workflowProgress.milestones.find(m => m.milestoneId === 'M3')?.status);
    if (id === 'B01') {
      add('income_precision', income?.status === 'approximate' && income.incomeBasis === 'net', 'approximate/net', income);
      const semantics = fact('debt_deduction_semantics', 'buying_unit');
      add('debt_semantics_unknown', !semantics || ['unknown', 'ambiguous', 'conflicting'].includes(semantics.status) || value(semantics) === 'unknown', 'unresolved', semantics);
    } else {
      const correctionId = 'laura-gross-correction-addition';
      const corrections = state.snapshot.assertions.filter(a => a.fieldId === 'declared_monthly_income' && a.evidenceRefs.some(r => r.messageId === correctionId));
      add('income_ambiguous', income?.status === 'ambiguous', 'ambiguous', income?.status);
      add('correction_evidence', hasEvidence(income, correctionId) && corrections.length > 0, correctionId, income?.evidenceRefs);
      add('no_invented_repeated_amount', corrections.length > 0 && corrections.every(a => a.value === undefined), 'no new numeric value', corrections.map(a => a.value));
    }
  }
  if (['B05', 'B06', 'B10'].includes(id)) {
    const income = fact('declared_monthly_income', 'participant');
    const v = value(income);
    const amount = v && typeof v === 'object' && !Array.isArray(v) && 'min' in v && 'max' in v ? v : null;
    add('income_range', !!amount && amount.min === 2000 && amount.max === 3000, '{min:2000,max:3000}', v);
    add('income_basis_unknown', income?.incomeBasis === 'unknown', 'unknown', income?.incomeBasis);
    add('no_unavailable_audio_evidence', !state.snapshot.assertions.some(a => a.evidenceRefs.some(r => r.messageId === 'javier-m4')), 'no audio evidence', 'javier-m4');
    if (id === 'B10') add('opt_out', blockers.includes('OPT_OUT'), 'OPT_OUT', blockers);
    else {
      add('trust', blockers.includes('TRUST'), 'TRUST', blockers);
      add('no_false_cost', !blockers.includes('COST'), 'no COST for routine price question', blockers);
    }
  }
  if (id === 'B08') {
    const income = fact('declared_monthly_income', 'buying_unit');
    const savings = fact('available_savings', 'buying_unit');
    const intent = fact('product_intent', 'case');
    add('joint_income_unknown_basis', value(income) === 1400 && (!income?.incomeBasis || income.incomeBasis === 'unknown'), '1400 unknown gross/net', income);
    add('savings_zero', value(savings) === 0, '0', value(savings));
    add('urgent', blockers.includes('URGENT'), 'URGENT', blockers);
    add('binding_claim', blockers.includes('BINDING_CLAIM'), 'BINDING_CLAIM', blockers);
    add('conditional_rental', !(intent?.status === 'known' && value(intent) === 'classical_rental'), 'not exclusive rental', intent);
  }
  if (state.action === 'CLARIFY' && state.draft !== null) add('draft_reviewable', state.draft === 'generated', 'generated', state.draft);
  return checks;
}

