  if (messages.some(m => m.messageId === 'javier-opt-out-addition')) signals.push({signalId:'opt',category:'OPT_OUT',evidenceRefs:[{messageId:'javier-opt-out-addition',quote:textOf(messages,'javier-opt-out-addition')}]});
